"""Validate saved assemblies and produce ROS models.

This module has no ROS or browser dependency. JSON uses metres and radians;
the editor converts those values to millimetres and degrees. The template keeps
the tested sensors/control plugins while editable parts change their geometry.
"""
import base64
import copy
import json
import math
from pathlib import Path
import re
import xml.etree.ElementTree as ET

IDENTIFIER = re.compile(r'^[A-Za-z][A-Za-z0-9_]{0,63}$')
SHAPES = {'assembly', 'box', 'cylinder', 'sphere', 'mesh'}
ROLES = {'fixed', 'left_wheel', 'right_wheel', 'lidar', 'camera'}
MAX_PARTS = 200
TEMPLATE = Path(__file__).parent / 'templates/reference.urdf'


def vector(value, name, lower, upper, length=3):
    if not isinstance(value, list) or len(value) != length:
        raise ValueError(f'{name} must contain {length} numbers.')
    if any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) or not lower <= x <= upper for x in value):
        raise ValueError(f'{name} must contain finite numbers between {lower} and {upper}.')


def validate(design):
    """Reject bad names, nonfinite transforms and oversized/imported data."""
    if not isinstance(design, dict) or design.get('schema_version') != 1:
        raise ValueError('Unsupported design version. Expected schema_version 1.')
    if not isinstance(design.get('name'), str) or not 1 <= len(design['name']) <= 100:
        raise ValueError('Give this design a name of 1–100 characters.')
    parts = design.get('parts')
    if not isinstance(parts, list) or not 1 <= len(parts) <= MAX_PARTS:
        raise ValueError(f'A design must contain 1–{MAX_PARTS} parts.')
    ids = set()
    reference = ET.parse(TEMPLATE).getroot()
    links = {x.get('name') for x in reference.findall('link')}
    targets = set()
    for p in parts:
        if not isinstance(p, dict) or not IDENTIFIER.fullmatch(str(p.get('id', ''))) or p['id'] in ids:
            raise ValueError('Part IDs must be unique letters/numbers/underscores starting with a letter.')
        ids.add(p['id'])
        if not isinstance(p.get('label'), str) or not 1 <= len(p['label']) <= 100:
            raise ValueError(f"{p['id']}: label must contain 1–100 characters.")
        if p.get('shape') not in SHAPES or p.get('role', 'fixed') not in ROLES:
            raise ValueError(f"{p['id']}: unsupported shape or role.")
        vector(p.get('xyz_m'), 'Position', -5, 5)
        vector(p.get('rpy_rad'), 'Rotation', -100, 100)
        vector(p.get('size_m'), 'Size', .0001, 5)
        vector(p.get('rgba'), 'Colour', 0, 1, 4)
        mass = p.get('mass_kg')
        if isinstance(mass, bool) or not isinstance(mass, (float, int)) or not math.isfinite(mass) or not .001 <= mass <= 100:
            raise ValueError(f"{p['id']}: mass must be between 0.001 and 100 kg.")
        if not isinstance(p.get('collision'), bool):
            raise ValueError('Collision must be true or false.')
        target = p.get('target')
        if target:
            key = (target.get('link'), target.get('visual'))
            if key in targets or key[0] not in links:
                raise ValueError('Duplicate or unknown template attachment.')
            targets.add(key)
            if key[1] and reference.find(f"link[@name='{key[0]}']/visual[@name='{key[1]}']") is None:
                raise ValueError('Unknown chassis visual attachment.')
        elif p.get('role', 'fixed') != 'fixed':
            raise ValueError('New parts are fixed attachments. Keep the supplied functional wheels and sensors.')
        if p['shape'] == 'mesh':
            mesh = p.get('mesh', {})
            try:
                data = base64.b64decode(mesh['base64'], validate=True)
            except (KeyError, ValueError) as exc:
                raise ValueError('Invalid STL data.') from exc
            if not 1 <= len(data) <= 8 * 1024 * 1024:
                raise ValueError('STL files must be no larger than 8 MB.')
            vector(mesh.get('scale'), 'Mesh scale', .000001, 100)
        for v in p.get('visuals', []):
            if v.get('shape') not in {'box', 'cylinder', 'sphere'}:
                raise ValueError('Unsupported assembly geometry.')
            vector(v.get('size_m'), 'Assembly size', .00001, 5)
            vector(v.get('xyz_m'), 'Assembly position', -5, 5)
            vector(v.get('rpy_rad'), 'Assembly rotation', -100, 100)
            vector(v.get('rgba'), 'Assembly colour', 0, 1, 4)
    return design


def drive_geometry(design):
    """Return usable wheel geometry; layout/export remains available without it."""
    validate(design)
    def role(name):
        found = [p for p in design['parts'] if p['role'] == name]
        if len(found) != 1:
            raise ValueError(f'Simulation requires exactly one {name.replace("_", " ")}.')
        return found[0]
    left, right = role('left_wheel'), role('right_wheel')
    role('lidar')
    if left['target'].get('link') != 'left_wheel' or right['target'].get('link') != 'right_wheel':
        raise ValueError('Keep each functional role on its supplied wheel.')
    if any(abs(a - b) > .0005 for a, b in zip(left['size_m'], right['size_m'])):
        raise ValueError('Drive wheels must have matching diameter and width.')
    for p in (left, right):
        if any(abs(a) > .001 for a in p['rpy_rad']):
            raise ValueError('Drive wheel axles must stay parallel to Y (wheel rotation 0, 0, 0).')
        if abs(p['size_m'][0] - p['size_m'][1]) > .0005:
            raise ValueError('Drive wheels must be round.')
        if abs(p['xyz_m'][2] - p['size_m'][0] / 2) > .001:
            raise ValueError('Set wheel centre Z to half its diameter so it touches the floor.')
    if abs(left['xyz_m'][0] - right['xyz_m'][0]) > .001:
        raise ValueError('The two drive wheels must share the same X coordinate.')
    separation = left['xyz_m'][1] - right['xyz_m'][1]
    if not .04 <= separation <= 2:
        raise ValueError('Left wheel must be to the left of the right wheel, separated by at least 40 mm.')
    lidar = role('lidar')
    if lidar['target'].get('link') != 'lidar_link':
        raise ValueError('Keep the lidar role on the supplied C1.')
    return {'wheel_radius_m': left['size_m'][0] / 2, 'wheel_separation_m': separation}


def text(values):
    return ' '.join(f'{x:.9g}' for x in values)


def geometry(parent, shape, size, mesh=None):
    node = ET.SubElement(parent, 'geometry')
    if shape == 'box':
        ET.SubElement(node, 'box', size=text(size))
    elif shape == 'cylinder':
        ET.SubElement(node, 'cylinder', radius=str(size[0] / 2), length=str(size[2]))
    elif shape == 'sphere':
        ET.SubElement(node, 'sphere', radius=str(size[0] / 2))
    elif shape == 'mesh':
        ET.SubElement(node, 'mesh', filename=mesh['uri'], scale=text(mesh['scale']))


def add_visual(link, p, xyz=None, rpy=None, name=None, mesh_uri=None):
    v = ET.SubElement(link, 'visual', name=name or p['id'])
    ET.SubElement(v, 'origin', xyz=text(xyz or [0, 0, 0]), rpy=text(rpy or [0, 0, 0]))
    geometry(v, p['shape'], p['size_m'], {'uri': mesh_uri, 'scale': p.get('mesh', {}).get('scale')} if mesh_uri else None)
    material = ET.SubElement(v, 'material', name=p['id'] + '_colour')
    ET.SubElement(material, 'color', rgba=text(p['rgba']))
    return v


def inertia(link, mass, size):
    old = link.find('inertial')
    if old is not None:
        link.remove(old)
    node = ET.SubElement(link, 'inertial')
    ET.SubElement(node, 'mass', value=str(mass))
    x, y, z = size
    ET.SubElement(node, 'inertia', ixx=str(mass * (y*y + z*z)/12), iyy=str(mass * (x*x + z*z)/12),
                  izz=str(mass * (x*x + y*y)/12), ixy='0', ixz='0', iyz='0')


def bounds(p):
    """Conservative XY bounds of a rotated component, including assembly details."""
    r, pitch, yaw = p['rpy_rad']
    cr, sr, cp, sp, cy, sy = math.cos(r), math.sin(r), math.cos(pitch), math.sin(pitch), math.cos(yaw), math.sin(yaw)
    matrix = [[cy*cp, cy*sp*sr-sy*cr, cy*sp*cr+sy*sr], [sy*cp, sy*sp*sr+cy*cr, sy*sp*cr-cy*sr], [-sp, cp*sr, cp*cr]]
    dimensions = list(p['size_m'])
    if p['role'] in ('left_wheel', 'right_wheel'):
        dimensions = [p['size_m'][0], p['size_m'][2], p['size_m'][0]]
    if p['shape'] == 'assembly' and p.get('visuals') and p['role'] not in ('left_wheel', 'right_wheel'):
        dimensions = [max(abs(v['xyz_m'][i]) + max(v['size_m'])/2 for v in p['visuals']) * 2 for i in range(3)]
    half = [sum(abs(matrix[i][j]) * dimensions[j]/2 for j in range(3)) for i in range(3)]
    return [p['xyz_m'][0] - half[0], p['xyz_m'][1] - half[1], p['xyz_m'][0] + half[0], p['xyz_m'][1] + half[1]]


def footprint(design):
    boxes = [bounds(p) for p in design['parts']]
    # Coordinates in base_link, matching Collision Monitor and Nav2.
    base = [-.03, 0, .116]
    xmin = min(x[0] for x in boxes) - base[0]
    ymin = min(x[1] for x in boxes) - base[1]
    xmax = max(x[2] for x in boxes) - base[0]
    ymax = max(x[3] for x in boxes) - base[1]
    return [[xmin, ymin], [xmax, ymin], [xmax, ymax], [xmin, ymax]]


def compile_model(design, mesh_prefix='package://vacuum_sim/meshes/design'):
    """Generate a full simulation URDF plus mesh files without mutating inputs."""
    validate(design)
    root = ET.parse(TEMPLATE).getroot()
    base = [-.03, 0, .116]
    parts = design['parts']
    retained_links = {p['target']['link'] for p in parts if p.get('target')}
    editable_links = {'left_wheel', 'right_wheel', 'caster', 'lidar_link', 'camera_link', 'left_nema17', 'right_nema17',
                      'left_tb6600', 'right_tb6600', 'arduino_mega', 'orange_pi5'}
    removed = editable_links - retained_links
    # Remove descendants (for example the camera optical frame) with their parent.
    changed = True
    while changed:
        changed = False
        for joint in root.findall('joint'):
            if joint.find('parent').get('link') in removed and joint.find('child').get('link') not in removed:
                removed.add(joint.find('child').get('link')); changed = True
    for node in list(root):
        if node.tag == 'link' and node.get('name') in removed:
            root.remove(node)
        elif node.tag == 'joint' and node.find('child').get('link') in removed:
            root.remove(node)
        elif node.tag == 'gazebo' and node.get('reference', '').replace('_joint', '') in removed:
            root.remove(node)
    body = root.find("link[@name='base_link']")
    for visual in list(body.findall('visual')):
        body.remove(visual)
    meshes = {}
    for p in parts:
        target = p.get('target', {})
        xyz = [p['xyz_m'][i] - base[i] for i in range(3)]
        if target.get('visual'):
            add_visual(body, p, xyz, p['rpy_rad'], target['visual'])
            continue
        if target.get('link'):
            link = root.find(f"link[@name='{target['link']}']")
            joint = next(j for j in root.findall('joint') if j.find('child').get('link') == target['link'])
            origin = joint.find('origin')
            origin.set('xyz', text(xyz)); origin.set('rpy', text(p['rpy_rad']))
            first = link.find('visual/geometry')[0]
            original_size = [float(x) for x in first.get('size').split()] if first.tag == 'box' else [float(first.get('radius')) * 2] * (3 if first.tag == 'sphere' else 2) + ([] if first.tag == 'sphere' else [float(first.get('length'))])
            scale = [p['size_m'][i] / original_size[i] for i in range(3)]
            if any(abs(x - 1) > 1e-9 for x in scale):
                for node in list(link.findall('visual')) + list(link.findall('collision')):
                    geom = node.find('geometry')[0]
                    if geom.tag == 'box':
                        geom.set('size', text([float(x) * scale[i] for i, x in enumerate(geom.get('size').split())]))
                    elif geom.tag in ('sphere', 'cylinder'):
                        geom.set('radius', str(float(geom.get('radius')) * scale[0]))

#!/usr/bin/env python3
"""Local designer API: versioned saves, exports and bounded simulator updates.

Bind only to loopback. Writes require the session token and a same-origin request.
No endpoint accepts shell commands or arbitrary filesystem paths.
"""
import argparse
import base64
from datetime import datetime, timezone
import hashlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import io
import json
import mimetypes
import os
from pathlib import Path
import secrets
import subprocess
import threading
import urllib.parse
import uuid
import zipfile

from model import compile_model, drive_geometry, footprint, hardware_description, validate

ROOT = Path(__file__).resolve().parents[1]
WEB = Path(__file__).parent / 'web'
MAX_BODY = 16 * 1024 * 1024
NAME = __import__('re').compile(r'^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$')


def atomic_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix('.tmp')
    tmp.write_text(json.dumps(value, indent=2) + '\n', encoding='utf-8')
    tmp.replace(path)


def revision(design):
    return hashlib.sha256(json.dumps(design, sort_keys=True).encode()).hexdigest()


class Store:
    def __init__(self, path):
        self.path = path
        path.mkdir(parents=True, exist_ok=True)
        self.lock = threading.Lock()
        if not (path / 'default.json').exists():
            atomic_json(path / 'default.json', json.loads((ROOT / 'designs/default.json').read_text()))

    def file(self, name):
        if not NAME.fullmatch(name):
            raise ValueError('Use letters, numbers, hyphens or underscores in the file name.')
        return self.path / (name + '.json')

    def load(self, name):
        with self.lock:
            design = json.loads(self.file(name).read_text())
            return {'design': design, 'revision': revision(design), 'file': name}

    def save(self, name, design, expected):
        validate(design)
        with self.lock:
            path = self.file(name)
            if path.exists():
                old = json.loads(path.read_text())
                if revision(old) != expected:
                    raise FileExistsError('This file changed in another editor. Reload it or save with a new name.')
                backup = self.path / 'history' / (name + '-' + datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f') + '.json')
                atomic_json(backup, old)
            atomic_json(path, design)
            return {'revision': revision(design), 'file': name}


def export_zip(design):
    model, meshes = compile_model(design)
    data = io.BytesIO()
    with zipfile.ZipFile(data, 'w', zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('design.json', json.dumps(design, indent=2))
        archive.writestr('robot.simulation.urdf', model)
        archive.writestr('robot.hardware.urdf', hardware_description(model))
        archive.writestr('README.txt', 'Coordinates: X forward, Y left, Z up. JSON: metres/radians.\nMeshes install into vacuum_sim/meshes/design.\nHardware URDF excludes Gazebo plugins. Firmware settings live separately in firmware/mega_drive.\n')
        for filename, content in meshes.items(): archive.writestr('meshes/' + filename, content)
    return data.getvalue()


def apply_to_workspace(design, workspace, progress):
    """Stop owned simulation, update model/controller/footprint, rebuild, then restart.

    An open driving panel owns manual-input.lock. Reject the operation instead of
    changing geometry under a live controller. Source changes roll back on failure.
    """
    import fcntl
    import yaml
    geometry = drive_geometry(design)
    if not workspace or not (workspace / 'src/vacuum_sim').is_dir():
        raise ValueError('Simulation workspace is unavailable. Save or export this design instead.')
    lock_path = workspace / '.lab/manual-input.lock'
    lock_path.parent.mkdir(exist_ok=True)
    with lock_path.open('a') as lock:
        try: fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as exc: raise ValueError('Close the driving panel before applying a design.') from exc
        # Reserve manual input until the model is fully rebuilt and restarted.
        run = lambda args, timeout=180: subprocess.run(args, cwd=workspace, text=True, capture_output=True, timeout=timeout)
        def checked(args, timeout=180):
            result = run(args, timeout)
            if result.returncode: raise RuntimeError((result.stdout + result.stderr)[-4000:])
            return result
        progress('Stopping simulation')
        checked(['python3', 'tools/lab_controller.py', 'stop'], 70)
        package = workspace / 'src/vacuum_sim'
        model, meshes = compile_model(design)
        updates = {package / 'urdf/designed.urdf': model.encode()}
        for name, content in meshes.items(): updates[package / 'meshes/design' / name] = content
        controllers = package / 'config/controllers.yaml'
        config = yaml.safe_load(controllers.read_text())
        params = config['diff_drive_controller']['ros__parameters']
        params.update(wheel_radius=geometry['wheel_radius_m'], wheel_separation=geometry['wheel_separation_m'])
        updates[controllers] = yaml.safe_dump(config, sort_keys=False).encode()
        fp = footprint(design)
        for filename in ('nav2.yaml', 'vacuum_nav2.yaml'):
            path = package / 'config' / filename
            config = yaml.safe_load(path.read_text())
            for name in ('local_costmap', 'global_costmap'):
                p = config[name][name]['ros__parameters']; p['footprint'] = str(fp)
            guard = config['collision_monitor']['ros__parameters']
            guard['FootprintApproach']['points'] = str(fp)
            # Preserve validated braking distances; expand the width for larger parts.
            width = max(abs(point[1]) for point in fp) + .05
            for zone in ('StopZone', 'SlowZone'):
                if zone not in guard or 'forward' not in guard[zone]: continue
                for direction in ('forward', 'reverse'):
                    points = json.loads(guard[zone][direction]['points'])
                    for point in points:
                        point[1] = width if point[1] > 0 else -width
                        if point[0] > 0: point[0] = max(point[0], max(x[0] for x in fp) + .15)
                        if point[0] < -.04: point[0] = min(point[0], min(x[0] for x in fp) - .15)
                    guard[zone][direction]['points'] = str(points)
            updates[path] = yaml.safe_dump(config, sort_keys=False).encode()
        # Bridge reports/radius use the same active design. Simulation caps stay unchanged.
        profile_path = workspace / 'tools/robot-profile.json'
        profile = json.loads(profile_path.read_text())
        profile['hardware']['wheel_diameter_m'] = geometry['wheel_radius_m'] * 2
        profile['hardware']['wheel_separation_m'] = geometry['wheel_separation_m']
        updates[profile_path] = (json.dumps(profile, indent=2) + '\n').encode()
        marker = workspace / '.lab/custom-design.json'
        updates[marker] = json.dumps({'design': design, 'revision': revision(design), 'footprint': fp}, indent=2).encode()
        backup = workspace / 'model-backups' / ('design-' + datetime.now().strftime('%Y%m%d-%H%M%S-%f'))
        originals = {p: p.read_bytes() if p.exists() else None for p in updates}
        for p, content in originals.items():
            if content is not None:
                saved = backup / p.relative_to(workspace); saved.parent.mkdir(parents=True, exist_ok=True); saved.write_bytes(content)
        try:
            progress('Building robot model')
            for p, content in updates.items(): p.parent.mkdir(parents=True, exist_ok=True); p.write_bytes(content)
            checked(['/bin/bash', '-lc', 'source env.sh; colcon build --symlink-install --packages-select vacuum_sim'])
            checked(['/bin/bash', '-lc', 'source env.sh; check_urdf src/vacuum_sim/urdf/designed.urdf'])
            progress('Starting simulation')
            checked(['python3', 'tools/lab_controller.py', 'drive'], 180)
        except Exception:
            run(['python3', 'tools/lab_controller.py', 'stop'], 70)
            for p, content in originals.items():
                if content is None: p.unlink(missing_ok=True)
                else: p.write_bytes(content)
            run(['/bin/bash', '-lc', 'source env.sh; colcon build --symlink-install --packages-select vacuum_sim'])
            raise
        return {'backup': str(backup), 'geometry': geometry, 'footprint': fp, 'revision': revision(design)}


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *_): pass

    def reply(self, status, body, content_type='application/json'):
        if not isinstance(body, bytes): body = json.dumps(body).encode()
        self.send_response(status)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers(); self.wfile.write(body)

    def authorized(self):
        host = self.headers.get('Host', '')
        if host not in (f'localhost:{self.server.server_port}', f'127.0.0.1:{self.server.server_port}'):
            return False
        origin = self.headers.get('Origin')
        if origin and origin not in (f'http://{host}',): return False
        return secrets.compare_digest(self.headers.get('X-Robot-Lab-Token', ''), self.server.token)

    def do_GET(self):
        url = urllib.parse.urlparse(self.path)
        if url.path.startswith('/api/'):
            if not self.authorized(): return self.reply(403, {'error': 'Open this editor from the launcher.'})
            try:
                query = urllib.parse.parse_qs(url.query)
