            except (ValueError, FileNotFoundError) as exc: return self.reply(400, {'error': str(exc)})
        path = (WEB / urllib.parse.unquote(url.path).lstrip('/')).resolve()
        if url.path == '/': path = WEB / 'index.html'
        if not path.is_relative_to(WEB) or not path.is_file(): return self.reply(404, {'error': 'File not found.'})
        self.reply(200, path.read_bytes(), mimetypes.guess_type(str(path))[0] or 'application/octet-stream')

    def do_POST(self):
        if not self.authorized(): return self.reply(403, {'error': 'Invalid editor session.'})
        try:
            size = int(self.headers.get('Content-Length', '0'))
            if not 0 < size <= MAX_BODY: return self.reply(413, {'error': 'Request exceeds 16 MB.'})
            data = json.loads(self.rfile.read(size))
