"""Shared ASCII/CRC wire contract. Keep in sync with firmware/protocol.h."""
from dataclasses import dataclass
import math


def crc16(data):
    crc = 0xffff
    for byte in data:
        crc ^= byte << 8
        for _ in range(8):
            crc = ((crc << 1) ^ (0x1021 if crc & 0x8000 else 0)) & 0xffff
    return crc


def frame(payload):
    raw = payload.encode('ascii')
    return raw + f',{crc16(raw):04X}\n'.encode('ascii')


def command(sequence, enabled, left, right):
    if not 0 <= sequence <= 65535 or any(isinstance(x, bool) or not isinstance(x, int) or abs(x) > 16000 for x in (left, right)):
        raise ValueError('Command outside protocol limits.')
    return frame(f'V1,{sequence},{1 if enabled else 0},{left},{right}')


@dataclass(frozen=True)
class Status:
    sequence: int
    armed: bool
    fault: int
    left_steps: int
    right_steps: int


def parse_status(raw):
    if len(raw) > 80:
        raise ValueError('Status frame too long.')
    payload, checksum = raw.rstrip(b'\r\n').rsplit(b',', 1)
    if len(checksum) != 4 or int(checksum, 16) != crc16(payload):
        raise ValueError('Invalid status checksum.')
    fields = payload.decode('ascii').split(',')
    if len(fields) != 6 or fields[0] != 'S1':
        raise ValueError('Invalid status frame.')
    numbers = [int(x) for x in fields[1:]]
    if not 0 <= numbers[0] <= 65535 or numbers[1] not in (0, 1) or not 0 <= numbers[2] <= 3 or any(not -(2**31) <= x < 2**31 for x in numbers[3:]):
        raise ValueError('Invalid status values.')
    return Status(numbers[0], bool(numbers[1]), *numbers[2:])


def wheel_rates(v, w, radius, separation, steps_per_rev, max_rate=16000):
    if any(not math.isfinite(x) for x in (v, w, radius, separation)) or radius <= 0 or separation <= 0 or steps_per_rev <= 0:
        raise ValueError('Invalid wheel geometry or velocity.')
    scale = steps_per_rev / (2 * math.pi * radius)
    rates = [(v - w * separation/2) * scale, (v + w * separation/2) * scale]
    # Scale both wheels together to preserve curvature when a pulse limit is hit.
    factor = min(1, max_rate / max(max(abs(x) for x in rates), 1))
    return tuple(round(x * factor) for x in rates)


def count_delta(current, previous):
    return (current - previous + 2**31) % 2**32 - 2**31

"""Bounded serial I/O worker with an independent caller heartbeat.

The ROS timer cannot block on USB. If it stops updating commands, this worker
disables motion even while the serial thread itself is still running.
"""
import threading
import time
from .protocol import command, parse_status


class SerialLink:
    def __init__(self, port, baud=115200, factory=None):
        self.port, self.baud, self.factory = port, baud, factory
        self.lock = threading.Lock()
        self.stop = threading.Event()
        self.desired = (False, 0, 0)
        self.updated = 0
        self.status = None
        self.received = 0
        self.connected = False
        self.error = 'Connecting'
        self.thread = threading.Thread(target=self.run, daemon=True)
        self.thread.start()

    def update(self, enabled, left, right):
        with self.lock:
            self.desired = (bool(enabled), int(left), int(right)); self.updated = time.monotonic()

    def snapshot(self):
        with self.lock: return self.connected, self.status, self.received, self.error

    def close(self):
        self.update(False, 0, 0); self.stop.set(); self.thread.join(2)

    def run(self):
        sequence = 0
        while not self.stop.is_set():
            serial = None
            try:
                if self.factory is None:
                    from serial import Serial
                    serial = Serial(self.port, self.baud, timeout=0, write_timeout=.1, exclusive=True)
                else: serial = self.factory()
                # Opening the Mega USB port may reset it. Zero frames cover its boot delay.
                with self.lock:
                    self.connected = True; self.status = None; self.error = 'Waiting for Mega'; self.desired = (False, 0, 0)
                buffer = b''
                while not self.stop.is_set():
                    with self.lock: desired, updated = self.desired, self.updated
                    if time.monotonic() - updated > .2: desired = (False, 0, 0)
                    packet = command(sequence, *desired)
                    if serial.write(packet) != len(packet): raise OSError('Incomplete serial write')
                    sequence = (sequence + 1) & 0xffff
                    buffer += serial.read(min(serial.in_waiting, 4096))
                    if len(buffer) > 4096: buffer = b''; raise OSError('Malformed serial stream')
                    while b'\n' in buffer:
                        raw, buffer = buffer.split(b'\n', 1)
                        try: status = parse_status(raw)
                        except (ValueError, UnicodeError): raise OSError('Mega checksum or status error')
                        with self.lock: self.status = status; self.received = time.monotonic(); self.error = ''
                    self.stop.wait(.02)
            except Exception as exc:
                with self.lock:
                    self.connected = False; self.status = None; self.error = str(exc); self.desired = (False, 0, 0)
                self.stop.wait(1)
            finally:
                if serial:
                    try: serial.write(command(sequence, False, 0, 0)); serial.close()
                    except Exception: pass

